import{_ as n,c as i,o as e,ae as s}from"./chunks/framework.BlRNOFgT.js";const k=JSON.parse('{"title":"Latihan Soal: Performance Engineering","description":"","frontmatter":{},"headers":[],"relativePath":"WBD/perfomance-eng.md","filePath":"WBD/perfomance-eng.md"}'),t={name:"WBD/perfomance-eng.md"};function l(r,a,u,o,m,p){return e(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="latihan-soal-performance-engineering" tabindex="-1">Latihan Soal: Performance Engineering <a class="header-anchor" href="#latihan-soal-performance-engineering" aria-label="Permalink to &quot;Latihan Soal: Performance Engineering&quot;">​</a></h1><h2 id="bagian-1-konsep-fundamental" tabindex="-1">Bagian 1: Konsep Fundamental <a class="header-anchor" href="#bagian-1-konsep-fundamental" aria-label="Permalink to &quot;Bagian 1: Konsep Fundamental&quot;">​</a></h2><p><strong>1. Manakah dari pernyataan berikut yang merupakan tujuan utama dari Performance Engineering dalam konteks pengembangan sistem?</strong></p><ul><li>A. Meningkatkan pendapatan dengan memastikan sistem bekerja optimal.</li><li>B. Menjamin kode bebas dari bug logika bisnis (Functional Errors).</li><li>C. Mengoptimalkan penyediaan (provisioning) dan pemanfaatan infrastruktur.</li><li>D. Menghindari kegagalan sistem yang mengharuskan pembuangan usaha pengembangan (scrapping development effort).</li><li>E. Membuat antarmuka pengguna (UI) menjadi lebih artistik dan modern.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, D</strong></p><p><strong>Penjelasan:</strong> Opsi B adalah ranah Functional Testing/Software Engineering, bukan fokus utama Performance Engineering. Opsi E berkaitan dengan UX/UI Design. Dokumen secara spesifik menyebutkan peningkatan revenue, optimalisasi infrastruktur, dan menghindari kegagalan total sebagai objektif.</p></details><hr><p><strong>2. Dalam Performance Engineering, performa dikategorikan ke dalam tiga pilar utama. Manakah di antara berikut ini yang termasuk dalam kategori tersebut?</strong></p><ul><li>A. Speed (Kecepatan)</li><li>B. Security (Keamanan)</li><li>C. Scalability (Skalabilitas)</li><li>D. Stability (Stabilitas)</li><li>E. Sustainability (Keberlanjutan Kode)</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, D</strong></p><p><strong>Penjelasan:</strong> Dokumen mendefinisikan &quot;3 S&quot; dalam kategori performa: Speed, Scalability, Stability. Security dan Sustainability adalah aspek kualitas perangkat lunak lainnya, namun bukan kategori utama dalam definisi Performance Engineering di dokumen ini.</p></details><hr><p><strong>3. Berdasarkan hukum dasar performa (Utilization Law dan Little&#39;s Law), manakah formula atau pernyataan yang BENAR?</strong></p><ul><li>A. $U = T \\times S$ (Utilization = Throughput $\\times$ Service Time).</li><li>B. Utilitas server tunggal ($U$) boleh melebihi 1 ($U &gt; 1$) dalam kondisi stabil.</li><li>C. $q = T \\times R$ (Queue Length = Throughput $\\times$ Response Time).</li><li>D. $R = T / q$ (Response Time = Throughput / Queue Length).</li><li>E. Hukum Little mengaitkan rata-rata panjang antrian, throughput, dan waktu respons.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, E</strong></p><p><strong>Penjelasan:</strong> Opsi B salah karena utilitas ($U$) harus $&lt; 1$ untuk server tunggal agar tidak jenuh total. Opsi D salah secara matematis berdasarkan turunan hukum Little ($R = q / T$).</p></details><hr><p><strong>4. Agar sebuah metrik performa dapat diandalkan dalam analisis teknik, properti apa saja yang harus dimilikinya?</strong></p><ul><li>A. Linearity (Linearitas).</li><li>B. Subjectivity (Subjektivitas).</li><li>C. Repeatability (Dapat diulang dengan hasil serupa).</li><li>D. Consistency (Konsistensi).</li><li>E. Complexity (Kompleksitas perhitungan).</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, D</strong></p><p><strong>Penjelasan:</strong> Metrik harus objektif, bukan subjektif (Opsi B salah). Metrik juga harus mudah diukur (Ease of Measurement), bukan kompleks (Opsi E salah). Properti yang valid meliputi reliabilitas, konsistensi, dan independensi.</p></details><hr><p><strong>5. Dalam konteks Performance Engineering untuk Web App, manakah praktik manajemen database yang DISARANKAN untuk menjaga performa?</strong></p><ul><li>A. Menggunakan <code>SELECT *</code> untuk memastikan semua data terambil agar fleksibel di sisi aplikasi.</li><li>B. Memisahkan proses Business Intelligence/Analytics dari pemrosesan transaksi utama.</li><li>C. Menghindari penggunaan <code>SORT BY</code> dan <code>GROUP BY</code> jika tidak sangat diperlukan.</li><li>D. Selalu melakukan <code>SELECT</code> untuk mengecek keberadaan data sebelum melakukan <code>UPDATE</code>.</li><li>E. Melakukan pengarsipan (archive) data lama daripada membiarkannya menumpuk di tabel aktif.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, E</strong></p><p><strong>Penjelasan:</strong> Opsi A adalah praktik buruk (bad practice) yang memboroskan I/O dan memori. Opsi D juga disarankan untuk dihindari (&quot;Avoid SELECT before UPDATE&quot;) karena menambah round-trip database yang tidak perlu; lebih baik gunakan mekanisme upsert atau update langsung dengan kondisi.</p></details><hr><h2 id="bagian-2-capacity-planning-design" tabindex="-1">Bagian 2: Capacity Planning &amp; Design <a class="header-anchor" href="#bagian-2-capacity-planning-design" aria-label="Permalink to &quot;Bagian 2: Capacity Planning &amp; Design&quot;">​</a></h2><p><strong>6. Saat merancang kapasitas untuk sistem transaksi dengan pendekatan &quot;Konservatif&quot; (Conservative Strategy), langkah apa yang sebaiknya diambil?</strong></p><ul><li>A. Mengasumsikan aplikasi mendapatkan 100% waktu CPU secara eksklusif.</li><li>B. Mengalokasikan target penggunaan CPU hanya 50% dari total kapasitas.</li><li>C. Mengasumsikan bahwa beban transaksi selalu merata (smooth) tanpa lonjakan.</li><li>D. Memperhitungkan pertumbuhan sistem di masa depan.</li><li>E. Mengabaikan overhead dari proses background (seperti update display atau backup DB).</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, D</strong></p><p><strong>Penjelasan:</strong> Opsi A, C, dan E adalah asumsi &quot;Optimis&quot; yang berbahaya dan sering menyebabkan kegagalan kapasitas. Pendekatan konservatif (Opsi B) memotong target menjadi setengah (50%) dan mengantisipasi sistem tidak linear/&quot;lumpy&quot; (Opsi D).</p></details><hr><p><strong>7. Manakah prinsip desain Web App yang secara langsung mendukung skalabilitas (scalability) sistem?</strong></p><ul><li>A. Stateless (Tanpa status di server).</li><li>B. Tightly Coupled (Sangat terikat antar komponen).</li><li>C. Asynchronous (Asinkron).</li><li>D. Loosely Coupled (Ketergantungan rendah antar komponen).</li><li>E. Synchronous Blocking (Pemrosesan sinkron yang memblokir).</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, C, D</strong></p><p><strong>Penjelasan:</strong> Tightly coupled dan Synchronous blocking adalah musuh skalabilitas karena menciptakan ketergantungan dan bottleneck. Skalabilitas didukung oleh arsitektur yang lepas, asinkron, dan tidak menyimpan state sesi di server aplikasi.</p></details><hr><p><strong>8. Dalam studi kasus, sistem mengalami masalah performa berkala karena adanya tugas &quot;Lumpy&quot; (menggumpal). Apa penyebab fenomena ini dalam contoh yang diberikan?</strong></p><ul><li>A. Validasi transaksi yang memakan waktu terlalu cepat.</li><li>B. Pembaruan tampilan (Display Update) yang berjalan setiap 10 detik.</li><li>C. Penyimpanan statistik ke Database yang dilakukan secara sinkron setiap 10 menit.</li><li>D. Kehabisan bandwidth jaringan secara tiba-tiba.</li><li>E. Penggunaan memori yang bocor (memory leak).</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C</strong></p><p><strong>Penjelasan:</strong> Dokumen menyoroti dua &quot;performance lumps&quot;: Update displays (setiap 10 detik) dan Write to DB (setiap 10 menit). Opsi D dan E mungkin masalah umum, tapi bukan konteks spesifik dari studi kasus &quot;lumpy distribution&quot; ini.</p></details><hr><p><strong>9. Selain CPU dan Memori, hal-hal apa saja yang harus dianggarkan (budgeted) dan dilacak terkait Page Load pada Web App?</strong></p><ul><li>A. Jumlah dan ukuran resource (gambar, skrip, dll).</li><li>B. Strategi Caching.</li><li>C. Waktu render di browser.</li><li>D. Latensi jaringan dan DNS lookup.</li><li>E. Jumlah baris komentar dalam kode HTML.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, C, D</strong></p><p><strong>Penjelasan:</strong> Semua opsi A-D disebutkan sebagai faktor &quot;Noteworthy&quot; untuk Page Load. Opsi E (komentar kode) tidak signifikan secara langsung terhadap metrik performa operasional dibandingkan ukuran file atau waktu render.</p></details><hr><p><strong>10. Kapan aktivitas Verify &amp; Validate model performa sebaiknya dilakukan?</strong></p><ul><li>A. Hanya di akhir proyek sebelum rilis (User Acceptance Test).</li><li>B. Dimulai sejak awal siklus hidup (life cycle) pengembangan.</li><li>C. Dilakukan terus menerus sepanjang siklus hidup proyek.</li><li>D. Hanya ketika terjadi keluhan dari pengguna.</li><li>E. Setelah sistem crash pertama kali.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C</strong></p><p><strong>Penjelasan:</strong> Dokumen menegaskan &quot;Begin early in the life cycle and continue throughout life cycle&quot;. Menunda hingga akhir (Opsi A) atau menunggu masalah (Opsi D/E) adalah pendekatan yang salah dalam Performance Engineering.</p></details><hr><h2 id="bagian-3-metrik-pemodelan" tabindex="-1">Bagian 3: Metrik &amp; Pemodelan <a class="header-anchor" href="#bagian-3-metrik-pemodelan" aria-label="Permalink to &quot;Bagian 3: Metrik &amp; Pemodelan&quot;">​</a></h2><p><strong>11. Bagaimana Response Time didefinisikan secara teknis dalam dokumen?</strong></p><ul><li>A. Waktu saat aktivitas dimulai dikurangi waktu saat aktivitas selesai.</li><li>B. Selisih antara waktu aktivitas selesai dengan waktu saat aktivitas diinisiasi.</li><li>C. Response Time = Wait Time + Service Time.</li><li>D. Hanya waktu yang dihabiskan CPU untuk memproses permintaan (Service Time).</li><li>E. Jumlah transaksi per detik.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C</strong></p><p><strong>Penjelasan:</strong> Opsi A terbalik. Opsi D hanya mencakup Service Time, padahal Response Time mencakup waktu tunggu antrian (Wait Time). Opsi E adalah definisi Throughput.</p></details><hr><p><strong>12. Dalam memodelkan performa, apa saja elemen kunci yang harus diidentifikasi dalam Performance Scenarios?</strong></p><ul><li>A. Identifikasi dan karakterisasi beban kerja (Workload).</li><li>B. Skenario Benchmark.</li><li>C. Persyaratan performa yang presisi (misal: Response time, Throughput).</li><li>D. Warna tombol pada antarmuka pengguna.</li><li>E. Anggaran biaya pemasaran produk.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, C</strong></p><p><strong>Penjelasan:</strong> Opsi D dan E tidak relevan dengan pemodelan teknis performa sistem. Elemen kuncinya adalah beban kerja, tolok ukur (benchmark), dan persyaratan kuantitatif (response time/throughput).</p></details><hr><p><strong>13. Manakah yang merupakan tantangan nyata dalam melakukan Performance Engineering?</strong></p><ul><li>A. Memilih alat (tool) yang tepat.</li><li>B. Mengidentifikasi masalah yang bersifat intermiten (kadang muncul, kadang tidak).</li><li>C. Mengatur perilaku pengguna simulasi agar sesuai dengan kebijakan/realita.</li><li>D. Menulis dokumentasi kode yang rapi.</li><li>E. Melakukan pengukuran waktu respons yang akurat.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, C, E</strong></p><p><strong>Penjelasan:</strong> Opsi D adalah praktik Software Engineering yang baik, tapi bukan tantangan spesifik dalam aktivitas testing dan tuning performa yang disebutkan dalam slide &quot;Challenges in PE&quot;.</p></details><hr><p><strong>14. Dokumen menyebutkan strategi &quot;Adapt-to-Precision&quot;. Apa maksud dari strategi ini?</strong></p><ul><li>A. Selalu menggunakan model yang paling kompleks sejak awal.</li><li>B. Menyesuaikan detail yang direpresentasikan dalam model dengan pengetahuan yang dimiliki tentang detail pemrosesan software.</li><li>C. Menggunakan estimasi kasus terbaik dan terburuk saja.</li><li>D. Memulai dengan model paling sederhana untuk mengidentifikasi masalah arsitektur.</li><li>E. Mengubah presisi model seiring bertambahnya informasi/kematangan desain.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, E</strong></p><p><strong>Penjelasan:</strong> Opsi A salah karena membuang sumber daya. Opsi C adalah &quot;Best and Worst-case Strategy&quot;. Opsi D adalah &quot;Simple-Model Strategy&quot;. Adapt-to-Precision berfokus pada kesesuaian tingkat detail model dengan pengetahuan yang tersedia saat itu.</p></details><hr><p><strong>15. Berdasarkan contoh kegagalan sistem perpajakan (E-Filing) dan Paspor yang dibahas, apa akar masalah utamanya?</strong></p><ul><li>A. Kode program tidak ditulis dengan bahasa Java.</li><li>B. Kapasitas jaringan dan bandwidth tidak mencukupi saat peak time (tenggat waktu).</li><li>C. Adanya permohonan fiktif (bogus applications) yang membebani sistem.</li><li>D. Pengguna lupa password mereka.</li><li>E. Kurangnya pengujian beban (load testing) yang memadai sebelum rilis.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, E</strong></p><p><strong>Penjelasan:</strong> Slide menyebutkan masalah bandwidth karena pelaporan di batas waktu (pajak) dan aplikasi fiktif yang membuat antrian sistem terjadwal (paspor). Ini mengindikasikan kegagalan dalam capacity planning dan testing (Opsi E adalah implikasi logis dari kegagalan tersebut). Opsi A dan D tidak relevan dengan studi kasus.</p></details><hr><h2 id="bagian-4-observability-optimization" tabindex="-1">Bagian 4: Observability &amp; Optimization <a class="header-anchor" href="#bagian-4-observability-optimization" aria-label="Permalink to &quot;Bagian 4: Observability &amp; Optimization&quot;">​</a></h2><p><strong>16. Untuk memastikan sistem dapat dipantau (observable), komponen apa yang harus diimplementasikan?</strong></p><ul><li>A. Log (Pencatatan kejadian).</li><li>B. Metrics (Data kuantitatif).</li><li>C. Traces (Penelusuran jejak request).</li><li>D. Comments (Komentar di dalam kode).</li><li>E. Unit Tests.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, C</strong></p><p><strong>Penjelasan:</strong> Dalam slide &quot;Web App Design&quot;, tiga pilar observabilitas yang disebut secara spesifik adalah Log, Metrics, dan Traces. Komentar dan Unit Test berguna untuk maintainability, bukan runtime observability.</p></details><hr><p><strong>17. Langkah apa yang dilakukan jika evaluasi model performa menunjukkan hasil &quot;Infeasible&quot; (Tidak Layak)?</strong></p><ul><li>A. Memodifikasi konsep produk.</li><li>B. Merevisi persyaratan performa.</li><li>C. Langsung melanjutkan ke tahap implementasi dan berharap terbaik.</li><li>D. Menambah sumber daya perangkat keras tanpa analisis.</li><li>E. Memodifikasi atau membuat skenario baru.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, E</strong></p><p><strong>Penjelasan:</strong> Berdasarkan diagram alir &quot;Modeling Performance&quot;, jika hasil evaluasi &quot;infeasible&quot;, panah mengarah ke: Modify product concept, Revise performance requirements, atau Modify/create scenarios. Mengabaikan hasil (Opsi C) adalah kesalahan fatal.</p></details><hr><p><strong>18. Terkait penggunaan Database Lock dalam studi kasus pembaruan statistik, apa dampak yang harus diwaspadai?</strong></p><ul><li>A. Locking meningkatkan concurrency sistem secara drastis.</li><li>B. Tindakan sinkronisasi (seperti menulis ke DB) dapat memblokir (&quot;lock out&quot;) bagian lain dari aplikasi.</li><li>C. Locking yang tidak bijak dapat menyebabkan masalah distribusi beban (&quot;lumps&quot;).</li><li>D. Locking memastikan data tidak pernah konsisten.</li><li>E. Penggunaan lock harus dilakukan dengan bijak (wisely).</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B, C, E</strong></p><p><strong>Penjelasan:</strong> Opsi A salah, locking justru menurunkan concurrency (karena antrian). Opsi B dan C adalah inti masalah pada studi kasus di mana update statistik memblokir transaksi selama beberapa detik. Opsi E adalah saran yang tertulis di slide.</p></details><hr><p><strong>19. Definisi yang benar mengenai Throughput adalah:</strong></p><ul><li>A. Waktu yang dibutuhkan untuk menyelesaikan satu tugas.</li><li>B. Laju (rate) di mana sistem menyelesaikan unit aktivitas tertentu.</li><li>C. Rasio antara waktu sibuk CPU dengan total waktu.</li><li>D. Jumlah total data yang tersimpan di database.</li><li>E. Kebalikan dari waktu respons (dalam kondisi tertentu).</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: B</strong></p><p><strong>Penjelasan:</strong> Opsi A adalah Service Time atau Response Time. Opsi C adalah Utilization. Throughput secara spesifik adalah rate (kecepatan per satuan waktu), misalnya transaksi per detik (TPS).</p></details><hr><p><strong>20. Aktivitas apa saja yang termasuk dalam cakupan kerja Performance Engineering?</strong></p><ul><li>A. Regression Test untuk performa.</li><li>B. Capacity Planning (Perencanaan Kapasitas).</li><li>C. System Diagnostics (Diagnostik Sistem/Profiling).</li><li>D. Performance Tuning and Optimization.</li><li>E. Functional Requirement Gathering.</li></ul><details class="details custom-block"><summary>Lihat Jawaban &amp; Pembahasan</summary><p><strong>Kunci Jawaban: A, B, C, D</strong></p><p><strong>Penjelasan:</strong> Opsi E (Pengumpulan kebutuhan fungsional) adalah bagian dari analisis sistem awal/Software Engineering umum. Performance Engineering fokus pada aspek non-fungsional (Testing, Tuning, Diagnostics, Capacity) seperti yang tertera pada slide &quot;Part of Performance Engineering&quot;.</p></details>',84)])])}const d=n(t,[["render",l]]);export{k as __pageData,d as default};
